INSERT INTO knowledge_base (source, category, title, content, metadata) VALUES
('David Goggins', 'motivation', 'The 40% Rule', 'When your mind is telling you that you''re done, that you''re exhausted, that you cannot possibly go any further, you''re only actually 40% done. Your mind gives up long before your body does. The key is to push past that mental barrier, to callus your mind the same way you callus your hands.', '{"book": "Can''t Hurt Me", "chapter": 4}'),
('David Goggins', 'motivation', 'Callousing the Mind', 'The only way to grow is to put yourself in uncomfortable situations. Do the hard things. Run when you don''t want to run. Study when you don''t want to study. The comfort zone is the enemy of growth. Every time you push through discomfort, you build a callus on your mind.', '{"book": "Can''t Hurt Me", "chapter": 5}'),
('David Goggins', 'relapse', 'Taking Souls', 'When you feel like quitting, remember why you started. The accountability mirror doesn''t lie. Look at yourself and ask: are you who you want to be? If not, get after it. No one is coming to save you. You have to save yourself.', '{"book": "Can''t Hurt Me", "chapter": 3}'),
('David Goggins', 'identity', 'The Accountability Mirror', 'Put post-it notes on your mirror with your goals, your insecurities, your lies. Face them every single morning. Be brutally honest with yourself. That''s the only way to change. You can''t fix what you won''t face.', '{"book": "Can''t Hurt Me", "chapter": 2}'),
('David Goggins', 'streaks', 'Stay Hard', 'Every day is a new opportunity to prove to yourself that you are who you say you are. Not through words, but through action. Stack the days. Build the evidence. Your identity changes when your behavior changes consistently.', '{"source": "interviews"}');
INSERT INTO knowledge_base (source, category, title, content, metadata) VALUES
('Marcus Aurelius', 'stoicism', 'Control What You Can', 'You have power over your mind, not outside events. Realize this, and you will find strength. The craving is not in your control. Your response to the craving IS. Focus on what you can control: your next action.', '{"book": "Meditations", "book_number": 6}'),
('Marcus Aurelius', 'stoicism', 'The Present Moment', 'Never let the future disturb you. You will meet it, if you have to, with the same weapons of reason which today arm you against the present. Do not fight tomorrow''s craving today. Win THIS moment.', '{"book": "Meditations", "book_number": 7}'),
('Marcus Aurelius', 'stoicism', 'Impermanence of Pain', 'Pain is neither intolerable nor everlasting if you bear in mind its limits. The craving will pass. It always passes. You just need to outlast it. Usually 15-20 minutes. That''s all. Can you be stronger than 20 minutes?', '{"book": "Meditations", "book_number": 7}'),
('Epictetus', 'stoicism', 'The Dichotomy of Control', 'Some things are within our power, while others are not. Within our power are opinion, motivation, desire, aversion — whatever is of our own doing. Not within our power are our body, property, reputation. The urge is not within your power. Your response is.', '{"book": "Enchiridion", "section": 1}'),
('Seneca', 'stoicism', 'On the Shortness of Life', 'It is not that we have a short time to live, but that we waste a great deal of it. Life is long enough if it is well spent. Every cigarette, every mindless scroll, every drink taken to numb — these are minutes of YOUR life you will never get back.', '{"book": "On the Shortness of Life"}');
INSERT INTO knowledge_base (source, category, title, content, metadata) VALUES
('James Clear', 'habits', 'Identity-Based Habits', 'The most effective way to change your habits is to focus not on what you want to achieve, but on who you wish to become. Every action you take is a vote for the type of person you wish to become. No single instance will transform your beliefs, but as the votes build up, so does the evidence of your new identity.', '{"book": "Atomic Habits", "chapter": 2}'),
('James Clear', 'habits', 'The Four Laws of Behavior Change', 'Make it obvious (cue). Make it attractive (craving). Make it easy (response). Make it satisfying (reward). To break a bad habit, invert: make it invisible, unattractive, difficult, and unsatisfying.', '{"book": "Atomic Habits", "chapter": 3}'),
('James Clear', 'habits', 'The Plateau of Latent Potential', 'Your habits seem to make no difference until you cross a critical threshold. The most powerful outcomes are delayed. You need to be patient. An ice cube doesn''t melt at 30 degrees. At 31 degrees, nothing happens. At 32 degrees, the ice begins to melt. One degree shift unlocked everything.', '{"book": "Atomic Habits", "chapter": 1}'),
('James Clear', 'streaks', 'Never Miss Twice', 'Missing once is an accident. Missing twice is the start of a new habit. The first mistake is never the one that ruins you. It''s the spiral of repeated mistakes that follows. Never miss twice.', '{"book": "Atomic Habits", "chapter": 16}'),
('James Clear', 'triggers', 'Environment Design', 'Environment is the invisible hand that shapes human behavior. If you want to break a bad habit, reduce exposure to the cue that causes it. Make the cues of your good habits obvious and the cues of your bad habits invisible.', '{"book": "Atomic Habits", "chapter": 6}');
INSERT INTO knowledge_base (source, category, title, content, metadata) VALUES
('Addiction Science', 'science', 'Neuroplasticity and Recovery', 'The brain physically changes with addiction — neural pathways strengthen with repeated use. But neuroplasticity works both ways. With each clean day, new pathways form. After 90 days, significant neural rewiring occurs. The cravings literally become weaker because the pathways weaken from disuse.', '{"type": "neuroscience"}'),
('Addiction Science', 'science', 'The Dopamine Cycle', 'Addictive behaviors hijack the dopamine system. The anticipation of the behavior releases more dopamine than the behavior itself. This is why cravings feel so powerful. Understanding this removes their mystery: it''s just chemistry, and chemistry can be changed.', '{"type": "neuroscience"}'),
('Addiction Science', 'science', 'The 90-Day Reset', 'Research shows that after approximately 90 days of abstinence from an addictive behavior, dopamine receptor density begins to normalize. Cravings significantly diminish. Cognitive function improves. This is not willpower — this is your brain literally healing itself.', '{"type": "neuroscience"}'),
('Addiction Science', 'triggers', 'HALT Protocol', 'Most relapses happen when you are Hungry, Angry, Lonely, or Tired (HALT). Before acting on any craving, check: am I HALT? Address the underlying need first. Often the craving disappears when the real need is met.', '{"type": "clinical_psychology"}'),
('Addiction Science', 'relapse', 'Relapse as Learning', 'A relapse is not a failure — it is DATA. It tells you exactly what your vulnerability windows are, what triggers are strongest, and what coping strategies failed. The most successful recoveries involve learning from relapses, not hiding from them.', '{"type": "clinical_psychology"}');
INSERT INTO knowledge_base (source, category, title, content, metadata) VALUES
('CBT', 'strategies', 'Urge Surfing', 'When a craving hits, don''t fight it or give in. Instead, observe it like a wave. Notice where you feel it in your body. Rate its intensity. Watch it rise, peak, and fall. Cravings typically last 15-20 minutes. If you can surf the urge, it will pass.', '{"type": "cognitive_behavioral_therapy"}'),
('CBT', 'strategies', 'The 10-Minute Rule', 'When tempted, tell yourself: "I''ll wait 10 minutes." Set a timer. During those 10 minutes, do something else — pushups, cold water on face, call someone, walk outside. Often the craving passes. If not, wait another 10.', '{"type": "cognitive_behavioral_therapy"}'),
('ACT', 'strategies', 'Values-Based Action', 'Ask yourself: "What kind of person do I want to be?" Then ask: "Does this behavior align with that person?" If the answer is no, you have your answer. You don''t need motivation — you need alignment with your values.', '{"type": "acceptance_commitment_therapy"}'),
('Practical', 'strategies', 'Implementation Intentions', 'Don''t just decide to quit. Plan the specific situations: "When [TRIGGER] happens, I will [ALTERNATIVE] instead." For example: "When I feel stressed after work, I will do 20 pushups instead of smoking." Specific plans are 2-3x more effective than vague intentions.', '{"type": "behavioral_psychology"}'),
('Practical', 'strategies', 'Social Accountability', 'Tell someone you trust about your goal. Check in with them daily. The knowledge that someone is watching makes you 65% more likely to succeed. Find your accountability partner — not someone who enables, but someone who challenges.', '{"type": "social_psychology"}');
INSERT INTO knowledge_base (source, category, title, content, metadata) VALUES
('Anna Lembke', 'science', 'Dopamine Nation: Pain and Pleasure', 'The secret to finding balance is combining the science of desire with the wisdom of recovery. We are all vulnerable to compulsive overconsumption. By embracing a period of abstinence, we reset our brain''s reward pathway and can enjoy simple pleasures again.', '{"book": "Dopamine Nation", "author": "Dr. Anna Lembke"}'),
('Allen Carr', 'methods', 'The Easy Way to Stop Smoking', 'The main reason smokers find it difficult to quit is the belief that they are giving up a genuine pleasure or crutch. Once you realize that the cigarette does nothing for you, and only relieves the withdrawal symptoms created by the previous cigarette, you can quit easily without willpower.', '{"book": "Easyway", "author": "Allen Carr"}'),
('Charles Duhigg', 'habits', 'The Habit Loop', 'Every habit follows a simple 3-step loop: Cue, Routine, Reward. To change a habit, you must keep the old cue, and deliver the old reward, but insert a new routine. You cannot extinguish a bad habit, you can only change it.', '{"book": "The Power of Habit", "author": "Charles Duhigg"}'),
('Johann Hari', 'psychology', 'The Opposite of Addiction is Connection', 'The core of addiction is about not wanting to be present in your life because your life is too painful. The solution isn''t just individual willpower, it''s deepening human connections. When we are happily connected to others, we don''t need to anesthetize ourselves.', '{"book": "Chasing the Scream", "author": "Johann Hari"}');
INSERT INTO knowledge_base (source, category, title, content, metadata) VALUES
('Andrew Huberman', 'science', 'Controlling Your Dopamine', 'Dopamine is not about pleasure, it''s about motivation, craving, and pursuit. If you spike your dopamine too high with cheap thrills, your baseline drops, making normal life feel miserable. The key is to attach dopamine to the EFFORT, not the reward.', '{"type": "youtube", "channel": "Huberman Lab", "url": "https://www.youtube.com/watch?v=QmOF0crdyRU"}'),
('Kurzgesagt', 'psychology', 'A Cure for Addiction', 'Addiction is often a symptom of a deeper problem: a lack of fulfilling environment and social bonds. In the famous "Rat Park" experiment, rats with friends and toys ignored the drug water. Isolation drives addiction. Connection heals it.', '{"type": "youtube", "channel": "Kurzgesagt", "url": "https://www.youtube.com/watch?v=ao8L-0nSYzg"}'),
('Terry Crews', 'motivation', 'Overcoming Porn Addiction', 'Pornography addiction thrives in secrecy. It kills intimacy and changes how you view people. The first step to freedom is acknowledging the problem out loud and shining a light on it. Shame grows in darkness, but it dies when exposed to the truth.', '{"type": "youtube", "topic": "Porn Addiction Recovery"}'),
('HealthyGamerGG', 'psychology', 'Why You Can''t Stop Binge Watching/Gaming', 'Technology is designed to hack your evolutionary drives. Your brain thinks it is achieving something real when you level up in a game. To stop, you must cultivate "Alexithymia" awareness: understand what negative emotion you are trying to suppress with the screen.', '{"type": "youtube", "channel": "HealthyGamerGG", "author": "Dr. K"}');
